package main

import "fmt"

func double(n int) int {
	return n * 2
}

func apply(nums []int, f func(int) int) []int {
	var out []int
	for _, n := range nums {
		out = append(out, f(n))
	}
	return out
}

func main() {
	nums := []int{1, 2, 3, 4}

	twice := double // a function value, no call yet
	fmt.Printf("%T %d\n", twice, twice(21))

	fmt.Println(apply(nums, double))
	fmt.Println(apply(nums, func(n int) int {
		return n * n
	}))
}

