package main

import "fmt"

func isEven(n int) bool {
	return n%2 == 0
}

func filter(nums []int, keep func(int) bool) []int {
	var out []int
	for _, n := range nums {
		if keep(n) {
			out = append(out, n)
		}
	}
	return out
}

func main() {
	nums := []int{4, 7, 12, 15, 20, 3}

	fmt.Println(filter(nums, isEven))
	fmt.Println(filter(nums, func(n int) bool {
		return n > 10
	}))
}

