package main

import "fmt"

func makeAccumulator(start int) func(int) int {
	total := start
	return func(n int) int {
		total += n
		return total
	}
}

func main() {
	acc := makeAccumulator(100)
	fmt.Println(acc(10))
	fmt.Println(acc(25))
	fmt.Println(acc(-5))
}

