package main

import "fmt"

func valueOf(n int) func() int {
	return func() int {
		return n
	}
}

func main() {
	var shared []func() int
	for i := 0; i < 3; i++ {
		shared = append(shared, func() int {
			return i
		})
	}
	fmt.Println(shared[0](), shared[1](), shared[2]())

	var copied []func() int
	for i := 0; i < 3; i++ {
		i := i // a new variable for this iteration only
		copied = append(copied, func() int {
			return i
		})
	}
	fmt.Println(copied[0](), copied[1](), copied[2]())

	var passed []func() int
	for i := 0; i < 3; i++ {
		passed = append(passed, valueOf(i)) // the argument is a copy
	}
	fmt.Println(passed[0](), passed[1](), passed[2]())
}

